-- Estonian and German versions of the text fields, edited in the editor next to the English ones.
-- Shape: {"et": {"summary": "…"}, "de": {…}}. A missing or empty field shows the English text.
alter table public.projects add column translations jsonb not null default '{}'::jsonb check (jsonb_typeof(translations) = 'object' and pg_column_size(translations) <= 1000000);
alter table public.posts add column translations jsonb not null default '{}'::jsonb check (jsonb_typeof(translations) = 'object' and pg_column_size(translations) <= 1000000);
alter table public.tools add column translations jsonb not null default '{}'::jsonb check (jsonb_typeof(translations) = 'object' and pg_column_size(translations) <= 20000);
alter table public.tool_groups add column translations jsonb not null default '{}'::jsonb check (jsonb_typeof(translations) = 'object' and pg_column_size(translations) <= 20000);
alter table public.site_settings add column translations jsonb not null default '{}'::jsonb check (jsonb_typeof(translations) = 'object' and pg_column_size(translations) <= 100000);

-- Starting translations for the original content, matched by slug, id or name, and only where none exist yet.
-- If you've rewritten a text since, its translation still describes the old version; check it in the editor.
update public.site_settings set translations = '{"et":{"location":"Eesti","headline":"Ehitan veebilehti, veebirakendusi ja mänge – enamasti selliseid asju, mida tahaksin ka ise kasutada.","introduction":"Praegu läheb suurem osa mu päevadest Casfyre''ile – vabakutseliste turuplatsile, mida ehitan nullist. Enne veebiasju tegin paar aastat mänge Unreal Engine''is ja C++-is, ja ausalt öeldes õppisin just seal suurema osa sellest, mida oskan.","about":"Ekraanist eemal meeldib mulle matkata ja looduses olla ning märgata pisiasju, millest enamik inimesi lihtsalt mööda kõnnib. Mängin ka trombooni ja mul on paar väikest lemmiklooma.\n\nRäägin eesti, inglise ja saksa keelt."},"de":{"location":"Estland","headline":"Ich baue Websites, Web-Apps und Spiele – meistens Dinge, die ich auch selbst benutzen würde.","introduction":"Gerade stecke ich die meisten Tage in Casfyre, einen Freelance-Marktplatz, den ich von Grund auf baue. Vor dem Web-Kram habe ich ein paar Jahre lang Spiele mit Unreal Engine und C++ gemacht, und ehrlich gesagt habe ich dort das meiste von dem gelernt, was ich kann.","about":"Abseits vom Bildschirm wandere ich gern, bin draußen in der Natur und achte auf die kleinen Dinge, an denen die meisten einfach vorbeigehen. Außerdem spiele ich Posaune und habe ein paar kleine Haustiere.\n\nIch spreche Estnisch, Englisch und Deutsch."}}'::jsonb where id = 1 and translations = '{}'::jsonb;
update public.projects set translations = '{"et":{"category":"Vabakutseliste turuplats","period":"2026 – praegu","summary":"Vabakutseliste turuplats, mida ehitan nullist. Leiad kellegi, arutate asja läbi, lepite töö kokku, maksad ja saad tulemuse – kõik ühes kohas.","thumbnail_alt":"Casfyre''i avaleht suure otsinguga, mis küsib, mida sul vaja teha on","gallery_alts":"Teenuse leht müüja, tarneaja ja kolme valitava paketiga\nKõikide kategooriate sirvimine, disainist muusika ja helini\nAbileht, mis selgitab Crafte, Calle ja Casefile''e","body":"## Mis see on\n\nCasfyre on Eestis tegutsev vabakutseliste turuplats digiteenustele. Müüjad avaldavad teenusepakette, ostjad saavad postitada lähteülesandeid ja enne tellimist saab kellelegi sõnumi kirjutada. Hinnale ei lisandu platvormitasu ning kui müüja ei võta tellimust 24 tunni jooksul vastu, saab ostja oma raha tagasi.\n\n## Osa, mis mulle korda läheb\n\nVabakutseline töö kipub lagunema igavates kohtades. Ulatus, mida keegi kunagi kirja ei pannud, failid kolmes eri rakenduses, keegi ei mäleta, milles kokku lepiti. Seepärast saab iga Casfyre''i tellimus Casefile''i: ulatus, vahe-etapid, failid, üleandmised, parandused ja otsused jäävad kõik selle töö külge, kuhu need kuuluvad.\n\n## Millega ma tegelen\n\nPraktiliselt kõigega. Otsing üle 400 teenuseliigi, sõnumid, pakkumised, fikseeritud hinnaga, etapiviisilised ja tunnipõhised tellimused, maksed, tõlked, juriidiline pool. See on suurim asi, mida olen seni ehitanud, ja just sinna läheb praegu suurem osa mu ajast.","lessons":"Pane otsus kirja enne koodi. Eriti maksete puhul: millal raha võtta, millal tagastada, mis tegelikult loeb nõustumiseks. Hoian nüüd lühikesi otsuste kirjeid ja need hoiavad mind kuu aja pärast sama asja uuesti vaidlemast.\nHüdratsioonivead on tavaliselt lihtsalt vigane HTML. Üks krahh taandus lingile teise lingi sees mobiili päises. Brauser parandas selle vaikselt enne Reacti laadimist ära, nii et kaks puud ei klappinud.\nKõik ei vaja otspunktkrüpteerimist. Tööalased sõnumid peavad olema otsitavad, raporteeritavad ja vaidluse korral ülevaadatavad, seega valisin ranged serveripoolsed ligipääsureeglid ja jätsin puhta koha, kuhu hiljem vajadusel krüpteerimine lisada.\nMajutuse kolimine on omaette projekt. Vercelist Cloudflare Workersisse kolimine tähendas cron-tööde, saladuste ja vahemälu ümbermõtlemist, mitte ainult juurutuskäsu vahetamist."},"de":{"category":"Freelance-Marktplatz","period":"2026 – heute","summary":"Ein Freelance-Marktplatz, den ich von Grund auf baue. Du findest jemanden, besprichst alles, einigt euch auf die Arbeit, bezahlst und bekommst das Ergebnis – alles an einem Ort.","thumbnail_alt":"Die Startseite von Casfyre mit einer großen Suche, die fragt, was du erledigt haben möchtest","gallery_alts":"Eine Service-Seite mit dem Verkäufer, der Lieferzeit und drei Paketen zur Auswahl\nAlle Kategorien durchstöbern, von Design bis Musik und Audio\nDie Hilfeseite, die Crafts, Calls und Casefiles erklärt","body":"## Was es ist\n\nCasfyre ist ein Freelance-Marktplatz für digitale Dienstleistungen mit Sitz in Estland. Verkäufer veröffentlichen Service-Pakete, Käufer können Briefings posten, und man kann jemandem schreiben, bevor man etwas bestellt. Auf den Preis kommt keine Plattformgebühr, und wenn ein Verkäufer eine Bestellung nicht innerhalb von 24 Stunden annimmt, bekommt der Käufer sein Geld zurück.\n\n## Der Teil, der mir wichtig ist\n\nFreelance-Arbeit scheitert meistens an den langweiligen Stellen. Ein Umfang, der nie aufgeschrieben wurde, Dateien verteilt über drei verschiedene Apps, niemand erinnert sich, was vereinbart war. Deshalb bekommt jede Bestellung auf Casfyre ein Casefile: Umfang, Meilensteine, Dateien, Lieferungen, Überarbeitungen und Entscheidungen bleiben alle an der Arbeit, zu der sie gehören.\n\n## Woran ich arbeite\n\nAn so ziemlich allem. Suche über mehr als 400 Arten von Dienstleistungen, Nachrichten, Angebote, Festpreis-, Meilenstein- und Stundenaufträge, Zahlungen, Übersetzungen, die rechtliche Seite. Es ist das Größte, was ich bisher gebaut habe, und dort steckt gerade der Großteil meiner Zeit.","lessons":"Schreib die Entscheidung vor dem Code auf. Vor allem bei Zahlungen: wann abgebucht wird, wann erstattet wird, was eigentlich als Zustimmung zählt. Ich führe jetzt kurze Entscheidungsnotizen, und die halten mich davon ab, einen Monat später dasselbe noch einmal auszudiskutieren.\nHydration-Fehler sind meistens einfach ungültiges HTML. Ein Absturz lag an einem Link in einem anderen Link im mobilen Header. Der Browser hat das still korrigiert, bevor React geladen war, und so passten die beiden Bäume nicht zusammen.\nNicht alles braucht Ende-zu-Ende-Verschlüsselung. Arbeitsnachrichten müssen durchsuchbar, meldbar und im Streitfall überprüfbar sein, also habe ich mich für strenge serverseitige Zugriffsregeln entschieden und eine saubere Stelle gelassen, an der später Verschlüsselung dazukommen kann, wo sie Sinn ergibt.\nEin Hosting-Umzug ist ein eigenes Projekt. Von Vercel zu Cloudflare Workers zu wechseln hieß, Cronjobs, Secrets und Caching neu zu durchdenken, nicht nur den Deploy-Befehl zu ändern."}}'::jsonb where slug = 'casfyre' and translations = '{}'::jsonb;
update public.projects set translations = '{"et":{"category":"Foorum","summary":"Foorumi ja pildilaua segu. Kogukonnad nagu Redditis, anonüümne postitamine nagu pildilaual ja nende vahel hulk modereerimise tööriistu.","thumbnail_alt":"Kanto populaarsete teemade voog eri kogukondade lõimedega, käivitatud lokaalselt näidispostitustega","gallery_alts":"Lõim vastustega, sorteeritud parimate järgi, anonüümsete ja sisse loginud postitajatega\nKogukondade kataloog, sorteeritud viimase tegevuse järgi","body":"## Mis see on\n\nKanto on foorum, kus inimesed loovad oma kogukondi, igaühel omad reeglid, sildid, paigutus ja moderaatorite tiim. Lõime ja vastuseid saab postitada anonüümselt, kui kogukond seda lubab, ja lisaks on hääletamine, mainimised, teavitused, otsesõnumid, jälgimine ja isikupärastatud voog.\n\n## Kuidas läks\n\nEhitasin selle umbes viie nädalaga, ligi 500 commitiga. Suur osa ajast läks asjadele, mida keegi ei näe: modereerimine ja raporteerimine, päringupiirangud, privaatsus ja andmete kustutamine, krüpteeritud otsesõnumid, õigused ja täielik adminipaneel. On ka asi nimega mikrolehed, kus saad foorumis otse liivakastis majutada väikese ühefailise HTML/CSS/JS projekti.\n\nPraegu see võrgus ei ole, aga see õpetas mulle tohutult sellise asja ehitamisest, kus teiste inimeste sisu ja turvalisus on osa tööst.","lessons":"Kiire ehitamine jätab auke. Umbes viie nädala pärast tegin oma koodile täieliku auditi ja see leidis otsingutulemustes salvestatud XSS-i ning tabelid ilma ridade tasemel turvalisuseta. Mõlemad said parandatud ja testitud, aga eelistan nüüd selliseid asju varem tabada.\nTurvalisus on palju väikeseid igavaid otsuseid. Skriptide nonce''id iga päringu kohta, päritolu kontrollid, mida töötajad näevad, kui kaua andmeid hoitakse. Nende ühte turvamudelisse kirja panemine lõpetas nende iganädalase uuesti otsustamise.\nAnonüümne postitamine on keerulisem, kui tundub. Inimesed peavad ikkagi saama oma postitusi kustutada ja moderaatorid neid modereerida, ilma et miski postitust avalikult kontoga seoks.\nDokumentatsioon triivib. Üks auditi leid oli lihtsalt see, et dokumentatsioon ütles üht ja kood tegi teist, nii et nüüd kontrollitakse dokumentatsiooni nagu koodi."},"de":{"summary":"Eine Mischung aus Forum und Imageboard. Communities wie bei Reddit, anonymes Posten wie auf einem Imageboard und dazwischen jede Menge Moderationswerkzeuge.","thumbnail_alt":"Kantos Trending-Feed mit Threads aus verschiedenen Communities, lokal mit Beispielbeiträgen","gallery_alts":"Ein Thread mit Antworten, nach den besten sortiert, mit anonymen und angemeldeten Nutzern\nDas Community-Verzeichnis, nach letzter Aktivität sortiert","body":"## Was es ist\n\nKanto ist ein Forum, in dem Leute ihre eigenen Communities gründen, jede mit eigenen Regeln, Tags, Layout und Mod-Team. Threads und Antworten können anonym gepostet werden, wo die Community es erlaubt, und obendrauf gibt es Votes, Erwähnungen, Benachrichtigungen, Direktnachrichten, Follows und einen personalisierten Feed.\n\n## Wie es lief\n\nIch habe es in etwa fünf Wochen gebaut, mit fast 500 Commits. Viel Zeit ging in Dinge, die niemand sieht: Moderation und Meldungen, Rate Limiting, Datenschutz und Datenlöschung, verschlüsselte Direktnachrichten, Berechtigungen und ein komplettes Admin-Panel. Außerdem gibt es sogenannte Micro-Sites, mit denen man ein kleines HTML/CSS/JS-Projekt aus einer einzigen Datei in einer Sandbox direkt im Forum hosten kann.\n\nGerade ist es nicht online, aber es hat mir enorm viel darüber beigebracht, etwas zu bauen, bei dem die Inhalte und die Sicherheit anderer Menschen Teil der Arbeit sind.","lessons":"Schnelles Bauen hinterlässt Lücken. Nach etwa fünf Wochen habe ich meinen eigenen Code komplett geprüft und dabei ein gespeichertes XSS in den Suchergebnissen und Tabellen ohne Row-Level-Security gefunden. Beides wurde behoben und getestet, aber so etwas fange ich jetzt lieber früher ab.\nSicherheit besteht aus vielen kleinen, langweiligen Entscheidungen. Script-Nonces pro Anfrage, Origin-Checks, was das Team sehen darf, wie lange Daten aufbewahrt werden. Sie in einem Sicherheitsmodell aufzuschreiben hat mich davon abgehalten, sie jede Woche neu zu entscheiden.\nAnonymes Posten ist schwieriger, als es klingt. Leute müssen ihre eigenen Beiträge trotzdem löschen und Mods sie moderieren können, ohne dass irgendetwas einen Beitrag offen mit einem Konto verbindet.\nDokumentation driftet. Eines der Ergebnisse der Prüfung war schlicht, dass die Doku das eine sagte und der Code etwas anderes tat, also wird Doku jetzt wie Code geprüft."}}'::jsonb where slug = 'kanto' and translations = '{}'::jsonb;
update public.projects set translations = '{"et":{"category":"Kliendi veebileht","summary":"Veebileht joogaõpetajale ja muusikule. Väljast rahulik ja ta saab kõike seal ise muuta.","thumbnail_alt":"Vaikusruumi avaleht, nimi seriifkirjas ja päikesesarnane logo","gallery_alts":"Pehme jooga ja gongi leht gongi fotoga\nEratunnid, igaühel kestus ja kontaktilink\nKKK, kus vastused avanevad ükshaaval","body":"## Mis see on\n\nVaikusruum on eestikeelne leht kundalini jooga, pehme jooga ja gongiseansside jaoks. Seal on lehed tundide ja eratundide kohta, KKK, kontakti- ja tagasisidevormid ning tutvustusleht.\n\n## Osa, mis mulle korda läheb\n\nLehte haldav inimene ei peaks kunagi mind vajama, et üht lauset muuta. Seepärast töötab kogu leht oma adminipaneeli pealt, kus ta saab muuta tekste, fotosid ja isegi tüpograafiat ilma koodi puudutamata. Kulutasin päris palju aega ka SEO-le, et leht tõesti välja tuleks, kui inimesed seda või selle taga olevat õpetajat otsivad, ilma ühegi võltsitud täitelehe.","lessons":"Kliendi väike muudatus on tavaliselt süsteemi probleem. Kui mõned tekstikastid ei võtnud reavahetusi vastu, oli päris lahendus üks ühine tekstisüsteem kõigile lehe plokkidele, mitte iga kasti eraldi lappimine.\nToimetaja on olulisem kui veebileht. Lehte haldav inimene kasutab adminit palju rohkem kui mina, seega läks suurem osa ajast muutmise ilmselgeks tegemisele: klõpsa tekstil, muuda, valmis.\nPlaneeri enne, kui puudutad kliendi elavat lehte. Alusta sellest, et vaatad olemasolevat ainult lugemiseks, pane kirja, mida „valmis“ tähendab, ja siis muuda asju väikeste sammudena.\nHea SEO ei vaja trikke. Korralikud pealkirjad, kirjeldused ja struktureeritud andmed tõid lehe otsingutesse ilma ühtegi võltslehte tegemata."},"de":{"category":"Kunden-Website","summary":"Eine Website für eine Yogalehrerin und Musikerin. Ruhig nach außen, und sie kann alles darauf selbst ändern.","thumbnail_alt":"Die Startseite von Vaikusruum mit dem Namen in einer Serifenschrift und dem sonnenartigen Logo","gallery_alts":"Die Seite zu sanftem Yoga und Gong mit einem Foto des Gongs\nEinzelstunden, jeweils mit Dauer und Kontaktlink\nDie FAQ, bei der sich die Antworten einzeln öffnen","body":"## Was es ist\n\nVaikusruum ist eine estnische Seite für Kundalini-Yoga, sanftes Yoga und Gong-Sessions. Es gibt Seiten zu den Kursen, Einzelstunden, eine FAQ, Kontakt- und Feedbackformulare und eine Über-mich-Seite.\n\n## Der Teil, der mir wichtig ist\n\nDie Person, die die Seite betreibt, sollte mich nie brauchen, um einen Satz zu ändern. Deshalb läuft die ganze Seite über ihr eigenes Admin-Panel, in dem sie Texte, Fotos und sogar die Typografie bearbeiten kann, ohne Code anzufassen. Außerdem habe ich viel Zeit in SEO gesteckt, damit die Seite wirklich auftaucht, wenn jemand nach ihr oder der Lehrerin dahinter sucht, ganz ohne Füllseiten.","lessons":"Eine kleine Änderung vom Kunden ist meistens ein Systemproblem. Als einige Textfelder keine Zeilenumbrüche annahmen, war die eigentliche Lösung ein gemeinsames Textsystem für jeden Block der Seite, nicht jedes Feld einzeln zu flicken.\nDer Editor ist wichtiger als die Website. Die Person, die die Seite betreibt, nutzt das Admin-Panel viel öfter als ich, also ging die meiste Zeit darein, das Bearbeiten offensichtlich zu machen: Text anklicken, ändern, fertig.\nErst planen, dann eine live laufende Kundenseite anfassen. Zuerst nur lesend anschauen, was da ist, aufschreiben, was „fertig“ bedeutet, und dann in kleinen Schritten ändern.\nGutes SEO braucht keine Tricks. Ordentliche Titel, Beschreibungen und strukturierte Daten haben die Seite in die Suchergebnisse gebracht, ohne eine einzige Fake-Seite."}}'::jsonb where slug = 'vaikusruum' and translations = '{}'::jsonb;
update public.projects set translations = '{"et":{"category":"Õudusmäng","summary":"Steamis olev ellujäämisõudusmäng tanklatöötajast, kelle kliendid pole päris inimesed. Minu esimene suur projekt.","thumbnail_alt":"Pime tankla öösel mängus The Last Customer, valikuga minna avastama või tööle","gallery_alts":"Valik kahe ukse vahel pimedas koridoris\nVannitoa sein, millele on kirjutatud COME HERE\nOstukäru lükkamine mööda hämarat poe vahekäiku","body":"## Mäng\n\nTöötad tanklas öövahetustes. Su sõber kaob ja tema leidmine viib sind läbi liminaalsete ruumide, mõistatuste ja asjade, mis teesklevad kliente. Mäng ilmus Steamis 2024. aasta oktoobris.\n\n## Ausalt öeldes\n\nSee oli mu esimene suur projekt ja tegin seda umbes pool aastat. See on paljudes kohtades konarlik ja kõik, mida ma praegu teeksin, oleks palju parem. Aga see ongi omamoodi mõte. Just seal õppisin päriselt mänguarendust: vaenlased, mõistatused, valikud, menüüd, valgustus ja terve mängu väljalaskmine. Peaaegu iga viga, mille seal tegin, õpetas mulle midagi, mida kasutan siiani.","lessons":"Lõpetamine on omaette oskus. Teekond „minu masinas töötab“ seisust päris Steami väljalaskeni (buildid, poeleht, treiler, ülevaatus) õpetas mulle rohkem kui ükski õpetus.\nPlaneeri varakult, kuidas süsteemid omavahel räägivad. Lisasin mehaanikaid jooksvalt juurde ja need läksid sassi, mis ongi suur põhjus, miks mäng konarlik tundub. Nüüd mõtlen struktuuri läbi enne, kui ehitama hakkan.\nÕudusmängu kannab atmosfäär. Valgustus, VHS-välimus ja tempo tegid rohkem kui ükski üksik mehaanika."},"de":{"category":"Horrorspiel","summary":"Ein Survival-Horror-Spiel auf Steam über einen Tankwart, dessen Kunden nicht ganz menschlich sind. Mein erstes großes Projekt.","thumbnail_alt":"Eine dunkle Tankstelle bei Nacht in The Last Customer, mit der Wahl, sich umzusehen oder zur Arbeit zu gehen","gallery_alts":"Die Wahl zwischen zwei Türen in einem dunklen Flur\nEine Badezimmerwand, auf der COME HERE steht\nMit einem Einkaufswagen durch einen düsteren Ladengang","body":"## Das Spiel\n\nDu arbeitest Nachtschichten an einer Tankstelle. Dein Freund verschwindet, und die Suche nach ihm führt dich durch liminale Räume, Rätsel und Dinge, die nur so tun, als wären sie Kunden. Es ist im Oktober 2024 auf Steam erschienen.\n\n## Ehrlich gesagt\n\nEs war mein erstes großes Projekt, und ich habe etwa ein halbes Jahr daran gearbeitet. An vielen Stellen ist es rau, und alles, was ich heute machen würde, wäre deutlich besser. Aber genau darum geht es irgendwie. Dort habe ich Spieleentwicklung wirklich gelernt: Gegner, Rätsel, Entscheidungen, Menüs, Beleuchtung und ein ganzes Spiel fertig rauszubringen. So ziemlich jeder Fehler, den ich dabei gemacht habe, hat mir etwas beigebracht, das ich heute noch nutze.","lessons":"Fertigmachen ist eine eigene Fähigkeit. Der Weg von „läuft auf meinem Rechner“ bis zu einem echten Steam-Release (Builds, Shopseite, Trailer, Prüfung) hat mir mehr beigebracht als jedes Tutorial.\nPlane früh, wie Systeme miteinander reden. Ich habe unterwegs immer neue Mechaniken hinzugefügt, und sie haben sich verheddert, was der Hauptgrund ist, warum sich das Spiel rau anfühlt. Heute denke ich über die Struktur nach, bevor ich anfange zu bauen.\nAtmosphäre trägt ein Horrorspiel. Die Beleuchtung, der VHS-Look und das Tempo haben mehr bewirkt als jede einzelne Mechanik."}}'::jsonb where slug = 'the-last-customer' and translations = '{}'::jsonb;
update public.projects set translations = '{"et":{"category":"Vokselmäng","period":"2026 – praegu","summary":"Vokselitel põhinev ellujäämismäng, mis püüab tabada Xbox 360 Minecrafti välimust ja tunnet. Väga varajane, seni peamiselt mootori ja maailma asjad.","thumbnail_alt":"Klotsiline savann laiade lamedate võradega puudega sinise taeva all","gallery_alts":"Kuusemets, genereeritud teisest seemnest\nInventari ja meisterdamise ekraan","body":"## Projekt\n\nCasmine on vokselitel põhinev ellujäämismäng, mida ehitan Godot''s. Eesmärk on vana Xbox 360 Minecrafti tunne: valgus, värvid, menüüd, jagatud ekraaniga ööd.\n\nSee on alles varajane. Praegu on see peamiselt maailma genereerimine, renderdamine, ellujäämise põhitõed nagu meisterdamine ja mitmikmängu alused. Iga maailm tuleb seemnest, nii et metsad, savannid ja koopad on iga kord erinevad.","lessons":"Lukusta oma tööriistad. Casmine töötab ühel kindlal kohandatud Godot'' buildil koos Voxel Toolsiga, mis on lukustatud versiooni ja kontrollsummaga, nii et see buildib iga kord samamoodi.\nMõõda enne, kui arvad. Hoian võrdlusmaailmu ja salvestustööriista, et saaksin kaadreid ja kaadriaegu enne ja pärast muudatust võrrelda, mitte tunde järgi minna.\nKasuta päris võrdlusmaterjali. Oma salvestuste võrdlemine päris Xbox 360 ekraanipiltidega näitab palju kiiremini, mis valesti on, kui ainult oma mängu vaatamine."},"de":{"category":"Voxel-Spiel","period":"2026 – heute","summary":"Ein Voxel-Survival-Spiel, das den Look und das Gefühl von Minecraft auf der Xbox 360 einfangen will. Sehr früh, bisher vor allem Engine- und Welt-Kram.","thumbnail_alt":"Eine klotzige Savanne mit breiten, flachkronigen Bäumen unter blauem Himmel","gallery_alts":"Ein Fichtenwald, aus einem anderen Seed generiert\nDer Inventar- und Crafting-Bildschirm","body":"## Das Projekt\n\nCasmine ist ein Voxel-Survival-Spiel, das ich in Godot baue. Das Ziel ist das Gefühl der alten Xbox-360-Edition von Minecraft: das Licht, die Farben, die Menüs, die Splitscreen-Abende.\n\nEs ist noch früh. Gerade geht es vor allem um Weltgenerierung, Rendering, die Survival-Grundlagen wie Crafting und das Fundament für Multiplayer. Jede Welt entsteht aus einem Seed, also sind die Wälder, Savannen und Höhlen jedes Mal anders.","lessons":"Pinne deine Werkzeuge. Casmine läuft auf einem bestimmten, angepassten Godot-Build mit Voxel Tools, festgelegt per Version und Prüfsumme, damit es jedes Mal gleich gebaut wird.\nMessen statt raten. Ich habe Benchmark-Welten und ein Aufnahme-Tool, damit ich Frames und Frame-Zeiten vor und nach einer Änderung vergleichen kann, statt nach Gefühl zu gehen.\nNimm eine echte Referenz. Meine Aufnahmen neben echte Xbox-360-Screenshots zu legen zeigt viel schneller, was nicht stimmt, als nur mein eigenes Spiel anzuschauen."}}'::jsonb where slug = 'casmine' and translations = '{}'::jsonb;
update public.projects set translations = '{"et":{"category":"Skriptikeel","summary":"Pisike skriptikeel. C++-is kirjutatud tekstiparser, mis käivitab .snaibo faile minu enda välja mõeldud lausetega.","thumbnail_alt":"Snaibo koodiredaktor lühikese skriptiga, mis kordab hello worldi","gallery_alts":"Käimas olev skript, mille väljund kordub väljundlogis\nUue .snaibo skriptifaili loomine","body":"Snaibo on väike projekt, kus kirjutasin C++-is lihtsa tekstiparseri. Saan lisada oma lauseid erinevate parameetritega ja siis saab kirjutada .snaibo faile ning neid väikeses koodiredaktoris käivitada. See on pooleli, aga see oli lõbus viis õppida, kuidas keelt tegelikult loetakse ja käivitatakse."},"de":{"category":"Skriptsprache","summary":"Eine winzige Skriptsprache. Ein Textparser in C++, der .snaibo-Dateien mit Anweisungen ausführt, die ich mir selbst ausgedacht habe.","thumbnail_alt":"Der Snaibo-Code-Editor mit einem kurzen Skript, das ein Hello World wiederholt","gallery_alts":"Ein laufendes Skript, dessen Ausgabe sich im Ausgabeprotokoll wiederholt\nEine neue .snaibo-Skriptdatei anlegen","body":"Snaibo ist ein kleines Projekt, bei dem ich einen einfachen Textparser in C++ geschrieben habe. Ich kann eigene Anweisungen mit verschiedenen Parametern hinzufügen, und dann kann man .snaibo-Dateien schreiben und in einem kleinen Code-Editor ausführen. Es ist unfertig, aber es war eine spaßige Art zu lernen, wie eine Sprache tatsächlich gelesen und ausgeführt wird."}}'::jsonb where slug = 'snaibo' and translations = '{}'::jsonb;
update public.projects set translations = '{"et":{"category":"Arkaadmäng","summary":"Flappy Bird, aga vanal VHS-kassetil. Tehtud ühe päevaga, lihtsalt et näha, mida ma päevaga suudan.","thumbnail_alt":"Väike lind lendamas roheliste torude vahel, kõige peal VHS-filter","gallery_alts":"Alguse menüü kolme raskusastmega\nMängu lõpu ekraan punktide ja rekordiga","body":"Ühepäevane projekt. Tegin selle üksi, mõne Sketchfabist laenatud tekstuuri ja assetiga, lihtsalt et näidata, mida ma päevaga teha suudan. Raskusastmed, rekord ja VHS-välimus kõige peal. Ma ei plaani seda tegelikult jätkata."},"de":{"category":"Arcade-Spiel","summary":"Flappy Bird, aber auf einer alten VHS-Kassette. An einem einzigen Tag gemacht, nur um zu sehen, was ich an einem Tag hinbekomme.","thumbnail_alt":"Ein kleiner Vogel fliegt zwischen grünen Rohren, über allem liegt ein VHS-Filter","gallery_alts":"Das Startmenü mit drei Schwierigkeitsstufen\nDer Game-Over-Bildschirm mit Punktestand und Highscore","body":"Ein Ein-Tages-Projekt. Ich habe es allein gemacht, mit ein paar Texturen und Assets von Sketchfab, nur um zu zeigen, was ich an einem Tag schaffe. Schwierigkeitsstufen, ein Highscore und ein VHS-Look über allem. Ich habe nicht wirklich vor, es weiterzuführen."}}'::jsonb where slug = 'flappy-vhs' and translations = '{}'::jsonb;
update public.projects set translations = '{"et":{"category":"E-pood","summary":"Kohalik e-pood lemmikloomatarvetele, peamiselt selgrootutele. See ei läinud päris käima ja praegu pole see enam võrgus.","thumbnail_alt":"Invert Nesti avaleht esiletõstetud lemmikloomatoodetega","gallery_alts":"Akvaariumi tooteleht tellimisvormiga\nKahepaiksete terraariumide kategooria leht","body":"Invert Nest oli e-pood, mille tegin oma piirkonna jaoks loomatarvetele, peamiselt selgrootute lemmikloomade tarvetele. Sain tooteid dünaamiliselt lisada ja inimesed said neid tellida. Kõik puhtas HTML-is, CSS-is ja JavaScriptis. See ei läinud nii hästi käima, kui lootsin, seega see enam ei tööta."},"de":{"summary":"Ein lokaler Webshop für Tierbedarf, vor allem für Wirbellose. Er ist nicht wirklich angekommen und jetzt offline.","thumbnail_alt":"Die Startseite von Invert Nest mit hervorgehobenen Tierprodukten","gallery_alts":"Eine Produktseite für ein Aquarium mit Bestellformular\nEine Kategorieseite für Amphibien-Terrarien","body":"Invert Nest war ein Webshop, den ich für meine Gegend gemacht habe, für Tierbedarf und vor allem Zubehör für wirbellose Haustiere. Ich konnte Produkte dynamisch hinzufügen, und die Leute konnten sie bestellen. Alles in reinem HTML, CSS und JavaScript. Er ist nicht so gut angekommen, wie ich gehofft hatte, deshalb läuft er nicht mehr."}}'::jsonb where slug = 'invert-nest' and translations = '{}'::jsonb;
update public.projects set translations = '{"et":{"category":"Seltskonnamäng","summary":"Jeopardy mäng oma redaktoriga, et saaksid teha oma mängulauad ja neid sõpradega mängida. Ehitatud ühe päevaga.","thumbnail_alt":"Jeopardy mängulaud nelja teema ja punktiväärtustega 100-st 500-ni","gallery_alts":"Alguse ekraan, kus valid võistkondade arvu\nMängulaualt avatud küsimus","body":"Lihtne Jeopardy mäng, mille tegin ühe päevaga. Sisseehitatud redaktoris saab teha oma mängulauad ja neid siis võistkondadega mängida. Kõik selles on minu ehitatud. Mängulaudu see veel faili ei salvesta, mis oleks ilmselge järgmine samm, kui selle juurde tagasi tulen."},"de":{"category":"Partyspiel","summary":"Ein Jeopardy-Spiel mit eigenem Editor, mit dem man eigene Spielbretter bauen und mit Freunden spielen kann. An einem Tag gebaut.","thumbnail_alt":"Ein Jeopardy-Spielbrett mit vier Themen und Punktwerten von 100 bis 500","gallery_alts":"Der Startbildschirm, auf dem man die Anzahl der Teams wählt\nEine vom Spielbrett geöffnete Frage","body":"Ein einfaches Jeopardy-Spiel, das ich an einem einzigen Tag gemacht habe. Im eingebauten Editor kann man eigene Spielbretter erstellen und sie dann in Teams spielen. Alles darin habe ich selbst gebaut. Es speichert Spielbretter noch nicht in eine Datei, was der offensichtliche nächste Schritt wäre, falls ich darauf zurückkomme."}}'::jsonb where slug = 'jeopardy' and translations = '{}'::jsonb;
update public.projects set translations = '{"et":{"category":"Mängu prototüüp","summary":"Iga sekundiga lähed natuke kiiremaks. Ühe Robloxi mänguidee uusversioon, tehtud erinevate mehaanikate proovimiseks.","thumbnail_alt":"Tegelane seisab värviliste uste ees Door of Fortune minimängus","gallery_alts":"Alguse ekraan\nJooksmine üle kaardi 400 meetri jooksu minimängust mööda","body":"Visandprojekt erinevate mehaanikate proovimiseks, põhineb Robloxi mängul, mis töötab umbes samamoodi. Iga sekundiga saad +1 kiirust ja saad mängida minu tehtud minimänge, et võita karikaid, mis annavad sulle veel rohkem kiirust sekundis."},"de":{"category":"Spielprototyp","summary":"Jede Sekunde wirst du ein bisschen schneller. Ein Remake einer Roblox-Spielidee, gemacht, um verschiedene Mechaniken auszuprobieren.","thumbnail_alt":"Eine Figur steht vor bunten Türen in einem Door-of-Fortune-Minispiel","gallery_alts":"Der Startbildschirm\nÜber die Karte rennen, vorbei an einem 400-Meter-Lauf-Minispiel","body":"Ein Wegwerfprojekt, um verschiedene Mechaniken auszuprobieren, basierend auf einem Roblox-Spiel, das ungefähr genauso funktioniert. Jede Sekunde bekommst du +1 Geschwindigkeit, und du kannst Minispiele spielen, die ich eingebaut habe, um Trophäen zu gewinnen, die dir noch mehr Geschwindigkeit pro Sekunde geben."}}'::jsonb where slug = 'plus-one-speed-per-second' and translations = '{}'::jsonb;
update public.projects set translations = '{"et":{"category":"Tornikaitsemäng","summary":"Põhimõtteliselt Plants vs Zombies kloon, mille tegin nullist lõbu pärast.","thumbnail_alt":"Ruuduline roheline muru, kus taimed kaitsevad end koletiste eest","gallery_alts":"Raskusastme valimine, taustal kreeka pähkel ja koletis","body":"Veel üks väike kõrvalprojekt, mille tegin lõbu pärast. See on põhimõtteliselt Plants vs Zombies kloon, ehitatud nullist mõne leitud tasuta assetiga. Seda oli väga lõbus teha."},"de":{"category":"Tower Defense","summary":"Im Grunde ein Plants-vs-Zombies-Klon, den ich zum Spaß von Grund auf gebaut habe.","thumbnail_alt":"Ein karierter grüner Rasen, auf dem sich Pflanzen gegen Monster verteidigen","gallery_alts":"Die Wahl der Schwierigkeit, mit einer Walnuss und einem Monster im Hintergrund","body":"Noch ein kleines Nebenprojekt, das ich zum Spaß gemacht habe. Im Grunde ein Plants-vs-Zombies-Klon, von Grund auf gebaut mit ein paar kostenlosen Assets, die ich gefunden habe. Das hat richtig Spaß gemacht."}}'::jsonb where slug = 'crops-vs-creeps' and translations = '{}'::jsonb;
update public.posts set translations = '{"et":{"title":"Koht projektimärkmetele","excerpt":"Väikesed otsused, asjad, mida olen õppinud, ja mida järgmisena teen.","body":"See on näidispostitus, et saaksid kirjutiste osa proovida enne andmebaasi ühendamist. Asenda see toimetajas oma sõnadega.\n\n## Mõned asjad, mida see koht mahutada saab\n\n- Edusammud käimasoleva projektiga\n- Huvitav probleem ja kuidas sa selle lahendasid\n- Midagi, mida proovisid ja mis ei töötanud\n\nSaad kasutada **Markdowni**, lisada linke, kirjutada koodi ja lisada pilte.\n\n```ts\nconst smallThings = [\"build\", \"notice\", \"improve\"];\n```\n\nPostitus võib jääda mustandiks, kuni oled valmis selle avaldama."},"de":{"title":"Ein Ort für Projektnotizen","excerpt":"Kleine Entscheidungen, Dinge, die ich gelernt habe, und was ich als Nächstes mache.","body":"Das ist ein Beispielbeitrag, damit du den Bereich für Texte ausprobieren kannst, bevor du eine Datenbank verbindest. Ersetze ihn im Editor durch deine eigenen Worte.\n\n## Ein paar Dinge, die hier Platz finden können\n\n- Fortschritte an einem laufenden Projekt\n- Ein interessantes Problem und wie du es gelöst hast\n- Etwas, das du ausprobiert hast und das nicht funktioniert hat\n\nDu kannst **Markdown** verwenden, Links einfügen, Code schreiben und Bilder einbinden.\n\n```ts\nconst smallThings = [\"build\", \"notice\", \"improve\"];\n```\n\nEin Beitrag kann ein Entwurf bleiben, bis du bereit bist, ihn zu veröffentlichen."}}'::jsonb where slug = 'a-place-for-project-notes' and translations = '{}'::jsonb;
update public.posts set translations = '{"et":{"title":"Märkmeid töölaualt","excerpt":"Teine näidispostitus lühemate uudiste ja pooleli ideede jaoks.","body":"See on veel üks näidispostitus. See näitab, kuidas lühemad märkmed sobituvad pikemate artiklite kõrvale.\n\nSuurt järeldust ei pea olema. Mõnikord piisab tähelepanekust.\n\n> Asenda need näidispostitused oma kirjutistega ja avalda need, kui need on valmis."},"de":{"title":"Notizen von der Werkbank","excerpt":"Ein zweiter Beispielbeitrag für kürzere Updates und unfertige Ideen.","body":"Das ist ein weiterer Beispielbeitrag. Er zeigt, wie kürzere Notizen neben längeren Artikeln wirken.\n\nEs muss kein großes Fazit geben. Manchmal reicht eine Beobachtung.\n\n> Ersetze diese Beispielbeiträge durch deine eigenen Texte und veröffentliche sie, wenn sie fertig sind."}}'::jsonb where slug = 'notes-from-the-workbench' and translations = '{}'::jsonb;
